56	 */
57	
58	@RestController
59	@CrossOrigin(exposedHeaders = "errors, content-type")
60	@RequestMapping("/api")
61	public class OwnerRestControllerV1 implements OwnersApi {
62	
63	    /**
64	     * Pattern for a syntactically valid email address: a non-empty local part, an '@', and a
65	     * dotted domain ending in a letters-only label. Applied to the trimmed, lower-cased value.
66	     */
67	    private static final Pattern EMAIL_PATTERN =
68	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$");
69	
70	    /**
71	     * Common address abbreviations expanded to their full form during address normalization.
72	     * Matching is performed per whitespace-separated token on the upper-cased value.
73	     */
74	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
75	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
76	
77	    private final ClinicService clinicService;
78	
79	    private final OwnerMapper ownerMapper;
80	
81	    private final PetMapper petMapper;
82	
83	    private final VisitMapper visitMapper;
84	
85	    public OwnerRestControllerV1(ClinicService clinicService,
86	                                 OwnerMapper ownerMapper,
87	                                 PetMapper petMapper,
88	                                 VisitMapper visitMapper) {
89	        this.clinicService = clinicService;
90	        this.ownerMapper = ownerMapper;
91	        this.petMapper = petMapper;
92	        this.visitMapper = visitMapper;
93	    }
94	
95	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
96	    @Override
97	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
98	        Collection<Owner> owners;
99	        if (lastName != null) {
100	            owners = this.clinicService.findOwnerByLastName(lastName);
101	        } else {
102	            owners = this.clinicService.findAllOwners();
103	        }
104	        if (owners.isEmpty()) {
105	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
106	        }
107	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
108	    }
109	
110	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
111	    @Override
112	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
113	        Owner owner = this.clinicService.findOwnerById(ownerId);
114	        if (owner == null) {
115	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
116	        }
117	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
118	    }
119	
120	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
121	    @Override
122	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
123	        HttpHeaders headers = new HttpHeaders();
124	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
125	        String address = normalizeAddress(owner.getAddress());
126	        if (address == null || address.isEmpty()) {
127	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
128	        }
129	        owner.setAddress(address);
130	        String telephone = toE164(owner.getTelephone());
131	        if (telephone == null) {
132	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
133	        }
134	        owner.setTelephone(telephone);
135	        if (owner.getRegistrationDate() == null) {
136	            owner.setRegistrationDate(LocalDate.now());
137	        }
138	        if (owner.getEmail() != null) {
139	            String email = normalizeEmail(owner.getEmail());
140	            if (!EMAIL_PATTERN.matcher(email).matches()) {
141	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
142	            }
143	            owner.setEmail(email);
144	        }
145	        boolean telephoneInUse = this.clinicService.findAllOwners().stream()
146	            .anyMatch(existing -> telephone.equals(toE164(existing.getTelephone())));
147	        if (telephoneInUse) {
148	            return new ResponseEntity<>(HttpStatus.CONFLICT);
149	        }
150	        String lastNameKey = householdKey(owner.getLastName());
151	        String addressKey = householdKey(owner.getAddress());
152	        List<Owner> householdMembers = this.clinicService.findAllOwners().stream()
153	            .filter(existing -> lastNameKey.equals(householdKey(existing.getLastName()))
154	                && addressKey.equals(householdKey(existing.getAddress())))
155	            .toList();
156	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
157	            String householdId = householdMembers.stream()
158	                .map(Owner::getHouseholdId)
159	                .filter(Objects::nonNull)
160	                .findFirst()
161	                .orElseGet(() -> householdId(owner));
162	            owner.setHouseholdId(householdId);
163	            for (Owner member : householdMembers) {
164	                if (member.getHouseholdId() == null) {
165	                    member.setHouseholdId(householdId);
166	                    this.clinicService.saveOwner(member);
167	                }
168	            }
169	        } else if (!householdMembers.isEmpty()) {
170	            return new ResponseEntity<>(HttpStatus.CONFLICT);
171	        }
172	        owner.setCustomerCode(nextCustomerCode(owner.getLastName()));
173	        this.clinicService.saveOwner(owner);
174	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
175	        headers.setLocation(UriComponentsBuilder.newInstance()
176	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
177	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
178	    }
179	
180	    /**
181	     * Normalizes a telephone number into E.164 form. Spaces, dashes and brackets are stripped.
182	     * When the value carries a leading {@code '+'} its country code is kept as given; otherwise the
183	     * Australian country code {@code '+61'} is assumed and a single leading {@code '0'} is dropped
184	     * from the national digits. The result must carry 8 to 15 digits after the {@code '+'}.
185	     *
186	     * @param telephone the raw telephone value (may be {@code null})
187	     * @return the E.164 telephone (e.g. {@code "+61412345678"}), or {@code null} if it cannot form
188	     *         a valid E.164 number
189	     */
190	    private String toE164(String telephone) {
191	        if (telephone == null) {
192	            return null;
193	        }
194	        String trimmed = telephone.trim();
195	        boolean hasCountryCode = trimmed.startsWith("+");
196	        String cleaned = trimmed.replaceAll("[\\s()\\[\\]-]", "");
197	        if (hasCountryCode) {
198	            cleaned = cleaned.substring(1);
199	        }
200	        if (!cleaned.matches("[0-9]+")) {
201	            return null;
202	        }
203	        String digits;
204	        if (hasCountryCode) {
205	            digits = cleaned;
206	        } else {
207	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
208	            digits = "61" + national;
209	        }
210	        if (digits.length() < 8 || digits.length() > 15) {
211	            return null;
212	        }
213	        return "+" + digits;
214	    }
215	
216	    /**
217	     * Normalizes an email address for storage by trimming surrounding whitespace and lower-casing
218	     * it. The result is validated by the caller against {@link #EMAIL_PATTERN}.
219	     *
220	     * @param email the raw email value (must not be {@code null})
221	     * @return the trimmed, lower-cased email
222	     */
223	    private String normalizeEmail(String email) {
224	        return email.trim().toLowerCase(Locale.ROOT);
225	    }
226	
227	    /**
228	     * Normalizes a postal address for storage and comparison: surrounding whitespace is trimmed,
229	     * internal runs of whitespace are collapsed to a single space, the value is upper-cased and
230	     * common street-type abbreviations are expanded per token ({@code ST -> STREET},
231	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). The stored and returned address is this
232	     * normalized form, and every household comparison uses it.
233	     *
234	     * @param address the raw address value (may be {@code null})
235	     * @return the normalized address, or {@code null} if the input was {@code null}
236	     */
237	    private String normalizeAddress(String address) {
238	        if (address == null) {
239	            return null;
240	        }
241	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
242	        if (collapsed.isEmpty()) {
243	            return collapsed;
244	        }
245	        String[] tokens = collapsed.split(" ");
246	        StringBuilder sb = new StringBuilder(collapsed.length());
247	        for (int i = 0; i < tokens.length; i++) {
248	            if (i > 0) {
249	                sb.append(' ');
250	            }
251	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
252	        }
253	        return sb.toString();
254	    }
255	
256	    /**
257	     * Normalizes a value for household-duplicate comparison: surrounding whitespace is trimmed,
258	     * internal runs of whitespace are collapsed to a single space and the result is lower-cased,
259	     * so that owners are compared case-insensitively with collapsed whitespace.
260	     *
261	     * @param value the raw value (must not be {@code null})
262	     * @return the normalized comparison key
263	     */
264	    private String householdKey(String value) {
265	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
266	    }
267	
268	    /**
269	     * Derives a stable, shared household identifier for the owner's household. The value is a
270	     * deterministic function of the normalized last name and address ({@link #householdKey}), so
271	     * every owner in the same household derives the identical identifier of the form
272	     * {@code 'HH-<12 upper-case hex>'}.
273	     *
274	     * @param owner the owner whose household identifier is derived
275	     * @return the stable household identifier
276	     */
277	    private String householdId(Owner owner) {
278	        String key = householdKey(owner.getLastName()) + "|" + householdKey(owner.getAddress());
279	        try {
280	            byte[] digest = MessageDigest.getInstance("SHA-256")
281	                .digest(key.getBytes(StandardCharsets.UTF_8));
282	            StringBuilder sb = new StringBuilder(digest.length * 2);
283	            for (byte b : digest) {
284	                sb.append(String.format("%02x", b));
285	            }
286	            return "HH-" + sb.substring(0, 12).toUpperCase(Locale.ROOT);
287	        }
288	        catch (java.security.NoSuchAlgorithmException e) {
289	            throw new IllegalStateException("SHA-256 not available", e);
290	        }
291	    }
292	
293	    /**
294	     * Builds the customer code for a newly registered owner in the form
295	     * {@code '<LAST3>-<NNNN>'}, where {@code LAST3} is the upper-cased first three letters
296	     * of the last name and {@code NNNN} is a global 4-digit zero-padded sequence equal to
297	     * one more than the current number of owners (e.g. {@code 'SMI-0007'}).
298	     *
299	     * @param lastName the owner's last name
300	     * @return the assigned customer code
301	     */
302	    private String nextCustomerCode(String lastName) {
303	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
304	        int sequence = this.clinicService.findAllOwners().size() + 1;
305	        return String.format(Locale.ROOT, "%s-%04d", last3, sequence);
306	    }
307	
308	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
309	    @Override
310	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
311	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
312	        if (currentOwner == null) {
313	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
314	        }
315	        String email = ownerFieldsDto.getEmail();
316	        if (email != null) {
317	            email = normalizeEmail(email);
318	            if (!EMAIL_PATTERN.matcher(email).matches()) {
319	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
320	            }
321	        }
322	        String telephone = toE164(ownerFieldsDto.getTelephone());
323	        if (telephone == null) {
324	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
325	        }
326	        currentOwner.setAddress(ownerFieldsDto.getAddress());
327	        currentOwner.setCity(ownerFieldsDto.getCity());
328	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
329	        currentOwner.setLastName(ownerFieldsDto.getLastName());
330	        currentOwner.setTelephone(telephone);
331	        currentOwner.setEmail(email);
332	        this.clinicService.saveOwner(currentOwner);
333	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
334	    }
335	
336	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
337	    @Transactional
338	    @Override
339	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
340	        Owner owner = this.clinicService.findOwnerById(ownerId);
341	        if (owner == null) {
342	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
343	        }
344	        this.clinicService.deleteOwner(owner);
345	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
346	    }
347	
348	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
349	    @Override
350	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
351	        Owner owner = this.clinicService.findOwnerById(ownerId);
352	        if (owner == null) {
353	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
354	        }
355	        HttpHeaders headers = new HttpHeaders();
356	        Pet pet = petMapper.toPet(petFieldsDto);
357	        owner.setId(ownerId);
358	        pet.setOwner(owner);
359	        pet.getType().setName(null);
360	        this.clinicService.savePet(pet);
361	        PetDto petDto = petMapper.toPetDto(pet);
362	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
363	            .buildAndExpand(pet.getId()).toUri());
364	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
365	    }
366	
367	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
368	    @Override
369	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
370	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
371	        if (currentOwner != null) {
372	            Pet currentPet = this.clinicService.findPetById(petId);
373	            if (currentPet != null) {
374	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
375	                currentPet.setName(petFieldsDto.getName());
376	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
377	                this.clinicService.savePet(currentPet);
378	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
379	            }
380	        }
381	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
382	    }
383	
384	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
385	    @Override
386	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
387	        HttpHeaders headers = new HttpHeaders();
388	        Visit visit = visitMapper.toVisit(visitFieldsDto);
389	        Pet pet = new Pet();
390	        pet.setId(petId);
391	        visit.setPet(pet);
392	        this.clinicService.saveVisit(visit);
393	        VisitDto visitDto = visitMapper.toVisitDto(visit);
394	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
395	            .buildAndExpand(visit.getId()).toUri());
396	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
397	    }
398	
399	
400	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
401	    @Override
402	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
403	        Owner owner = this.clinicService.findOwnerById(ownerId);
404	        if (owner != null) {
405	            Pet pet = owner.getPet(petId);
406	            if (pet != null) {
407	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
408	            }
409	        }
410	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
411	    }
412	}
